                                            Throwable ex,
                                            String s) throws IOException {
    if (printFailure) System.out.println();
    wt_err.flush(printFailure);
    wt_out.flush(printFailure);
    if (printFailure) {
        System.out.println(s);
        ex.printStackTrace();
        fail(whoami());
    } else {
        System.out.println(s);
        fail(ex.getMessage() + " " + whoami());
    }
}

